80	/// Shares identical props between components, as the structural resolver does: a design system's components repeat
81	/// the same few hundred props, and Chakra's 600 components would otherwise hold 470,000 copies.
82	#[derive(Debug, Default)]
83	pub struct PropInterner {
84	    by_hash: Mutex<FxHashMap<u64, Vec<Arc<SemanticProp>>>>,
85	}
86	
87	impl PropInterner {
88	    /// The one shared copy of `prop`: an equal prop interned earlier, or `prop` itself the first time. If the internal
89	    /// lock is poisoned it returns `prop` unshared rather than failing.
90	    pub fn share(&self, prop: SemanticProp) -> Arc<SemanticProp> {
91	        let hash = prop.structural_hash();
92	        let Ok(mut by_hash) = self.by_hash.lock() else { return Arc::new(prop) };
93	        let bucket = by_hash.entry(hash).or_default();
94	        if let Some(existing) = bucket.iter().find(|existing| ***existing == prop) {
95	            return existing.clone();
96	        }
97	        let shared = Arc::new(prop);
98	        bucket.push(shared.clone());
99	        shared
100	    }
101	}
