128	/// The backend's answer for a run. A backend that could not start returns no components and one diagnostic, never an
129	/// error: the structural result is always a complete answer on its own.
130	#[derive(Debug, Clone, Default, PartialEq)]
131	pub struct SemanticOutcome {
132	    /// The components the checker answered for; each replaces the props of the structural entry it names.
133	    pub components: Vec<SemanticComponent>,
134	    /// The requested components the checker left to the structural result, each with its reason.
135	    pub fallbacks: Vec<SemanticFallback>,
136	    /// What the backend itself reports (it could not start, it timed out); merged into the output's diagnostics.
137	    pub diagnostics: Vec<Diagnostic>,
