140	/// A component the checker may be asked about.
141	#[derive(Debug, Clone, PartialEq, Eq)]
142	pub struct SemanticTarget {
143	    /// The component's output key. Its answer, or its fallback, carries it back, and the merge finds the entry by it:
144	    /// never by file and display name, which two components can share.
145	    pub key: String,
146	    /// The file that declares the component.
147	    pub file_path: Utf8PathBuf,
148	    /// The component's display name, for messages; the checker does not look the component up by it.
149	    pub display_name: String,
150	    /// How the module exports the component ([`ComponentEntry::exports`]): the checker asks for it by exactly these.
151	    /// It answers only for exported components and reports the rest as fallbacks.
152	    pub exports: Vec<ComponentExport>,
153	    /// Props the structural pass already has a description for. The checker is not asked for those: it is 65% of
154	    /// the requests on Mantine, and the merge keeps the structural description when the checker's is empty.
155	    pub described: rustc_hash::FxHashSet<String>,
156	    /// Which props `@types/react` declares the checker reports: `None` for all of them, else only these names. The
157	    /// session decides from `htmlAttributes` (`react_types::react_props_wanted`); the checker never filters by itself.
158	    pub react_wanted: Option<rustc_hash::FxHashSet<String>>,
159	}
