    /// Publish `next` and free what it replaces on another thread. A large project's revision takes tens of
    /// milliseconds to drop, and the caller only wants the new one out. `replaced` is the caller's own reference to
    /// the revision `next` was built from: whichever reference goes last pays for the free, so it must not be this
    /// thread's.
    fn publish(&self, next: Arc<Revision>, replaced: Arc<Revision>) {
        free_in_background((self.current.swap(Some(next)), replaced));
    }

    /// Drop what the checker said and tell it what changed: a new revision may have changed a file the answers depend
    /// on. Called before the revision is published, so no request sees the new files with an old answer.
    fn forget_checker_answers(&self, change: SourceChange) {
        if let Some(hook) = &self.semantic {
            hook.invalidate(change);
        }
    }

    /// The published revision's number: 0 before `initialize`, then one higher for every change that produced a new
    /// revision. An update that leaves it unchanged changed nothing.
    pub fn revision(&self) -> u64 {
        self.current.load().as_ref().map_or(0, |revision| revision.id)
    }

    /// The current output: exactly what a cold `extract()` of the same files would return. Empty before `initialize`.
    pub fn snapshot(&self) -> ExtractionOutput {
        match self.current.load_full() {
            Some(revision) => (*revision.output).clone(),
            None => empty_output(),
        }
    }

    /// The current output, shared rather than copied. `None` before `initialize`.
    pub fn current_output(&self) -> Option<Arc<ExtractionOutput>> {
        self.current.load_full().map(|revision| revision.output.clone())
    }

    /// The component published under `key`, with its own diagnostics. A lazy session resolves it now, or answers from
    /// what an earlier request resolved; the answer is the one a batch extraction of the same files publishes under
    /// that key. `None` for a key with no component, and before `initialize`.
    pub fn component(&self, key: &str) -> Option<ComponentAnswer> {
        let revision = self.current.load_full()?;
        let answer = match revision.is_lazy() {
            true => {
                let answer = revision.lazy_component(&self.options, key);
                revision.load_whole_demand_in_background(&self.options);
                answer
            }
            false => revision.published_component(key),
        };
        self.refined(answer, Priority::Interactive)
    }

    /// `answer` with the attached checker's props, when there is a checker and it answers within the wait `priority`
    /// gives it.
    fn refined(&self, answer: Option<ComponentAnswer>, priority: Priority) -> Option<ComponentAnswer> {
        match (&self.semantic, answer) {
            (Some(hook), Some(answer)) => Some(hook.refine(answer, self.options.html_attributes, priority)),
            (_, answer) => answer,
        }
    }

