#[test]
fn provenance_names_the_resolved_components_and_each_fallback_reason() {
    let mut out = output();
    let outcome = SemanticOutcome {
        components: vec![button(vec![])],
        fallbacks: vec![SemanticFallback { key: "Card".to_string(), reason: "not exported".to_string() }],
