// Runs the built provider inside a worker thread, as Storybook's docgen worker does: each message is one docgen request.
import { parentPort } from 'node:worker_threads'
import { createDocgenProvider } from '../../../dist/provider.js'

const provider = (await createDocgenProvider({ srcDirs: ['src'] }))(async () => ({ id: 'next' }))

parentPort.on('message', async (entry) => {
  // oxlint-disable-next-line unicorn/require-post-message-target-origin -- a worker port has no origin
  parentPort.postMessage(await provider({ entry }))
})
import type { Meta, StoryObj } from '@storybook/react-vite'
import Menu from '../components/Menu'

// A default export that is `Object.assign(Root, { Item })`: the story's `Menu` is the component declared as `Root`.
const meta = { component: Menu } satisfies Meta<typeof Menu>
export default meta

export const Basic: StoryObj<typeof meta> = { args: { open: true } }
interface RootProps {
  /** Whether the menu shows its items. */
  open?: boolean
}

interface ItemProps {
  /** The text of the item. */
  label: string
}

const Root = ({ open = false }: RootProps) => <ul hidden={!open} />

const Item = ({ label }: ItemProps) => <li>{label}</li>

export default Object.assign(Root, { Item })
src
import { defineConfig } from 'vitest/config'

// pool: 'forks': the tests change the working directory, which the provider's worker thread shares.
export default defineConfig({
  test: {
    pool: 'forks',
    include: ['tests/integration/**/*.test.ts'],
    testTimeout: 15000,
  },
})

